CREATE OR REPLACE FUNCTION public.audit_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE meta jsonb := '{}'::jsonb; BEGIN IF TG_TABLE_NAME='appointments' AND TG_OP='UPDATE' THEN meta=jsonb_build_object('old_start',to_jsonb(old)->'starts_at','new_start',to_jsonb(new)->'starts_at','old_status',to_jsonb(old)->'status','new_status',to_jsonb(new)->'status'); END IF; INSERT INTO public.audit_events(clinic_id,actor,event,entity_id,metadata) VALUES(new.clinic_id,auth.uid(),TG_TABLE_NAME||':'||TG_OP,new.id,meta); RETURN new; END $$;